// 1. Haal de data op uit de vorige nodes
const slot = $('Format Data').first().json.slot;
const stepA = $('Claude Step A').first().json;
const stepB = $('Claude Step B').first().json;
const stepC = $('Claude Step C').first().json;

// 2. Extractie met fallback (indien missing) -- alle drie stappen gebruiken tool use,
//    dus de output staat altijd in content[0].input, nooit in content[0].text
const rationale = stepA?.content?.[0]?.input?.rationale || '';
const headline = stepB?.content?.[0]?.input?.headline || '';
const content = stepB?.content?.[0]?.input?.content || '';
const suggestions = stepC?.content?.[0]?.input || {};

if (!rationale || !headline || !content) {
  throw new Error('Claude Step A of B miste input data.');
}

// 3. Return de definitieve objecten voor de Insert node
return {
  json: {
    slot_id: String(slot.id),
    rationale: String(rationale),
    headline: String(headline),
    content_ai: String(content),
    tone_suggested: String(suggestions.tone || 'b2b'),
    angle_suggested: String(suggestions.angle || 'general'),
    image_ratio_suggested: String(suggestions.image_ratio || 'landscape'),
    platform_suggested: String(suggestions.platform || 'linkedin'),
    hashtags_suggested: Array.isArray(suggestions.hashtags) ? suggestions.hashtags.join(', ') : '',
    status: 'draft'
  }
};
